const deriveWrongReason = (question: QuestQuestion): WrongReason => {
  if (question.numberLine || question.interactiveNumberLine || /수직선|점|화살표/.test(question.prompt)) return "수직선 읽기";
  if (/요금|조건|모두|각각|둘 다|두 조건/.test(question.prompt)) return "조건 모두 확인";
  if (/올림|버림|반올림|묶음|상자|병|줄/.test(question.prompt)) return "올림·버림·반올림";
  if (/이상|이하|초과|미만/.test(question.prompt)) return "경계값 포함·제외";
  return "문제 정보 읽기";
};

