const emptyRecords = (): Records => Object.fromEntries(quests.map((quest) => [quest.id, { accuracy: 0, attempts: 0, hints: 0, completed: false }])) as Records;
const formatTime = (seconds: number) => `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
const noteKey = (questId: number, questionIndex: number) => `${questId}-${questionIndex}`;
const normalizeAnswer = (value: string) => value.replace(/[\s,]/g, "").trim();
const isAnswerCorrect = (answers: string[], selected: string[]) => selected.length > 0 && answers.length === selected.length && answers.every((answer) => selected.some((value) => normalizeAnswer(value) === normalizeAnswer(answer)));
const buildMiniReviewQueue = (notes: WrongNote[], questId: number): MiniReviewItem[] => {
  const seen = new Set<string>();
  const remember = (question: QuestQuestion, source: MiniReviewItem["source"], sourceQuestId = questId): MiniReviewItem | null => {
    if (seen.has(question.prompt)) return null;
    seen.add(question.prompt);
    return { ...question, questId: sourceQuestId, source };
  };
  const fromNotes = notes.filter((note) => note.questId === questId).sort((a, b) => b.wrongCount - a.wrongCount).map((note) => remember(note, "오답 확인")).filter((item): item is MiniReviewItem => Boolean(item));
  const reinforcement = quests[questId - 1].questions.map((question) => remember(question, "약점 강화")).filter((item): item is MiniReviewItem => Boolean(item));
  return [...fromNotes, ...reinforcement].slice(0, 5);
};
const buildReasonReviewQueue = (notes: WrongNote[], reason: WrongReason): MiniReviewItem[] => {
  const seen = new Set<string>();
  const queue: MiniReviewItem[] = [];
  const add = (question: QuestQuestion, questId: number, source: MiniReviewItem["source"]) => { if (queue.length >= 5 || seen.has(question.prompt) || deriveWrongReason(question) !== reason) return; seen.add(question.prompt); queue.push({ ...question, questId, source }); };
  notes.filter((note) => deriveWrongReason(note) === reason).sort((a, b) => b.wrongCount - a.wrongCount).forEach((note) => add(note, note.questId, "오답 확인"));
  quests.forEach((quest) => quest.questions.forEach((question) => add(question, quest.id, "약점 강화")));
  return queue;
};

/** Design: deterministic SVG keeps every tick, endpoint, and inclusion state mathematically readable. */
function NumberLineDiagram({ model }: { model: NumberLineModel }) {
  const values = Array.from({ length: Math.round((model.max - model.min) / model.step) + 1 }, (_, index) => Number((Number((model.min + index * model.step).toFixed(6))).toFixed(6)));
  const x = (value: number) => 30 + ((value - model.min) / (model.max - model.min)) * 480;
  const markerId = `number-line-arrow-${model.min}-${model.max}-${model.start}-${model.end ?? "edge"}-${model.direction}`;
  const startX = x(model.start);
  const endX = model.end === undefined ? undefined : x(model.end);
  const rangeStart = model.direction === "left" ? 30 : startX;
  const rangeEnd = model.direction === "right" ? 510 : model.direction === "between" && endX !== undefined ? endX : startX;
  return <figure className="number-line" aria-label="수직선 그림"><figcaption><span>수직선 판독</span><b>범위선은 끝점에서 시작해 화살표 방향으로 이어져요.</b></figcaption><svg viewBox="0 0 540 104" role="img" aria-label="범위를 나타낸 수직선"><defs><marker id={markerId} viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto-start-reverse"><path d="M 1 1 L 11 6 L 1 11 z" fill="currentColor" /></marker></defs><line x1="24" y1="44" x2="516" y2="44" className="number-line__axis" />{model.direction !== "between" && <line x1={rangeStart} y1="44" x2={rangeEnd} y2="44" className="number-line__range" markerEnd={model.direction === "right" ? `url(#${markerId})` : undefined} markerStart={model.direction === "left" ? `url(#${markerId})` : undefined} />}{model.direction === "between" && <line x1={rangeStart} y1="44" x2={rangeEnd} y2="44" className="number-line__range" />}{values.map((value) => <g key={value}><line x1={x(value)} y1="35" x2={x(value)} y2="54" className="number-line__tick" /><text x={x(value)} y="77" textAnchor="middle" className="number-line__label">{value}</text></g>)}<circle cx={startX} cy="44" r="8" className={model.startIncluded ? "number-line__point number-line__point--closed" : "number-line__point"} />{endX !== undefined && <circle cx={endX} cy="44" r="8" className={model.endIncluded ? "number-line__point number-line__point--closed" : "number-line__point"} />}</svg></figure>;
}

function QuestionVisualCard({ visual, selected = [], onSelect }: { visual: QuestionVisual; selected?: string[]; onSelect?: (value: string) => void }) {
  if (visual.type === "place-value") return <figure className="place-value-card"><figcaption>{visual.value} · {visual.place}까지 올림</figcaption><div><strong>{visual.kept}</strong><mark>{visual.tail}</mark></div><p>색칠한 부분은 남길 자리의 아래 부분이에요. 이 부분이 모두 0인지 살펴보세요.</p></figure>;
  if (visual.type === "parcel") return <figure className="parcel-card"><figcaption>상자의 세 변을 더해 크기를 구해요</figcaption><svg viewBox="0 0 420 235" role="img" aria-label={`가로 ${visual.dimensions[0]}cm, 세로 ${visual.dimensions[1]}cm, 높이 ${visual.dimensions[2]}cm 상자`}><path d="M100 80 230 40 330 90 200 135Z" fill="#ffdc9b" stroke="#957149" strokeWidth="2"/><path d="M100 80 200 135 200 215 100 160Z" fill="#f7bc78" stroke="#957149" strokeWidth="2"/><path d="M200 135 330 90 330 170 200 215Z" fill="#e7a45f" stroke="#957149" strokeWidth="2"/><text x="110" y="195">{visual.dimensions[0]}cm</text><text x="265" y="210">{visual.dimensions[1]}cm</text><text x="345" y="135">{visual.dimensions[2]}cm</text></svg><p>무게 {visual.weight}kg · 크기는 가로 + 세로 + 높이</p></figure>;
  if (visual.type === "rate-table") return <figure className="learning-visual learning-visual--rate"><figcaption><span>실생활 표 읽기</span><b>{visual.title}</b></figcaption><table><thead><tr><th>무게</th><th>세 변의 합</th><th>요금</th></tr></thead><tbody>{visual.rows.map((row) => <tr key={`${row.range}-${row.size}`}><td>{row.range}</td><td>{row.size}</td><td><strong>{row.fee}</strong></td></tr>)}</tbody></table><p>무게와 크기로 요금을 각각 찾고, 두 요금 중 더 높은 요금을 내요. 두 요금을 더하지 않아요.</p></figure>;
  if (visual.type === "rounding-line") return <figure className="learning-visual learning-visual--rounding-line"><figcaption><span>반올림 수직선</span><b>{visual.title}</b></figcaption><div className="rounding-line__labels"><span>{visual.lower}</span><strong>{visual.value}</strong><span>{visual.upper}</span></div><div className="rounding-line__axis"><i /><i /><i /><b style={{ left: "50%" }}>{visual.value}</b></div><div className="rounding-line__ends"><span>{visual.lower}까지 거리 {visual.value - visual.lower}</span><span>{visual.upper}까지 거리 {visual.upper - visual.value}</span></div><p>{visual.value}는 {visual.lower}과 {visual.upper} 중 <strong>{visual.target}</strong>에 더 가까워 {visual.rounded}로 반올림해요.</p></figure>;
  if (visual.type === "rounding-builder") return <figure className="learning-visual learning-visual--rounding-line rounding-builder"><figcaption><span>반올림 수직선 조작</span><b>{visual.title}</b></figcaption><div className="rounding-line__labels"><span>{visual.lower}</span><strong>{visual.value}</strong><span>{visual.upper}</span></div><div className="rounding-line__axis"><i /><i /><i /><b style={{ left: "50%" }}>{visual.value}</b></div><div className="rounding-line__ends"><span>아래 경계까지 {visual.value - visual.lower}</span><span>위 경계까지 {visual.upper - visual.value}</span></div><p>두 경계 중 반올림 결과가 될 수를 직접 골라 보세요.</p><div className="rounding-builder__choices">{[visual.lower, visual.upper].map((choice) => <button type="button" key={choice} className={selected.includes(String(choice)) || selected.includes(choice.toLocaleString("ko-KR")) ? "is-selected" : ""} onClick={() => onSelect?.(choice.toLocaleString("ko-KR"))}>{choice.toLocaleString("ko-KR")}</button>)}</div></figure>;
  const groupCount = Math.min(visual.completed, 10);
  const dots = Math.min(visual.groupSize, 12);
  return <figure className={`learning-visual learning-visual--bundle learning-visual--${visual.item === "상자" ? "box" : "stamp"}`}><figcaption><span>{visual.purpose === "all" ? "모두 담기" : "완성 묶음"}</span><b>{visual.title}</b></figcaption><div className="bundle-visual__groups">{Array.from({ length: groupCount }, (_, group) => <div className="bundle-visual__group" key={group}><i>{Array.from({ length: dots }, (_, dot) => <em key={dot} />)}</i><b>{visual.groupSize}{visual.item === "상자" ? "권" : "장"}</b></div>)}{visual.remainder > 0 && <div className="bundle-visual__remainder"><i>{Array.from({ length: Math.min(visual.remainder, 6) }, (_, dot) => <em key={dot} />)}</i><b>남은 {visual.remainder}{visual.item === "상자" ? "권" : "장"}</b></div>}</div><p>전체 {visual.total}{visual.item === "상자" ? "권" : "장"} · 한 묶음 {visual.groupSize}{visual.item === "상자" ? "권" : "장"}</p></figure>;
}

function InteractiveNumberLine({ model, value, onChange }: { model: NumberLineModel; value: string; onChange: (value: string) => void }) {
  const parts = value.split("|");
  const point = parts[0] === "" ? undefined : Number(parts[0]);
  const included = parts[1] !== "exclude";
  const direction = parts[2] === "left" ? "left" : "right";
  const values = Array.from({ length: Math.floor((model.max - model.min) / model.step) + 1 }, (_, index) => Number((model.min + index * model.step).toFixed(6)));
  const x = (number: number) => 28 + ((number - model.min) / (model.max - model.min)) * 484;
  const setAnswer = (nextPoint = point, nextIncluded = included, nextDirection = direction) => { if (nextPoint === undefined) return; onChange(`${nextPoint}|${nextIncluded ? "include" : "exclude"}|${nextDirection}`); };
  const rangeStart = direction === "left" ? 30 : point === undefined ? 0 : x(point);
  const rangeEnd = direction === "right" ? 510 : point === undefined ? 0 : x(point);
  const markerId = `interactive-arrow-${model.min}-${model.max}`;
  return <section className="number-line-builder" aria-label="수직선 직접 표현"><div className="number-line-builder__heading"><span>직접 표현</span><b>점 · 포함 여부 · 화살표를 완성하세요.</b></div><svg viewBox="0 0 540 112" role="img" aria-label="조작할 수 있는 수직선"><defs><marker id={markerId} viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto-start-reverse"><path d="M 1 1 L 11 6 L 1 11 z" fill="currentColor" /></marker></defs><line x1="22" y1="48" x2="518" y2="48" className="number-line__axis" />{point !== undefined && <line x1={rangeStart} y1="48" x2={rangeEnd} y2="48" className="number-line-builder__range" markerEnd={direction === "right" ? `url(#${markerId})` : undefined} markerStart={direction === "left" ? `url(#${markerId})` : undefined} />}{values.map((number) => <g key={number} className="number-line-builder__tick" onClick={() => setAnswer(number)} role="button" aria-label={`${number}에 점 찍기`}><line x1={x(number)} y1="36" x2={x(number)} y2="61" className="number-line__tick" /><circle cx={x(number)} cy="48" r={point === number ? 9 : 6} className={point === number ? (included ? "number-line__point number-line__point--closed" : "number-line__point") : "number-line-builder__target"} /><text x={x(number)} y="84" textAnchor="middle" className="number-line__label">{number}</text></g>)}</svg><div className="number-line-builder__controls"><div><span>점의 모양</span><button type="button" className={included ? "is-active" : ""} onClick={() => setAnswer(point, true)}>● 포함</button><button type="button" className={!included ? "is-active" : ""} onClick={() => setAnswer(point, false)}>○ 제외</button></div><div><span>화살표</span><button type="button" className={direction === "left" ? "is-active" : ""} onClick={() => setAnswer(point, included, "left")}>← 작은 수</button><button type="button" className={direction === "right" ? "is-active" : ""} onClick={() => setAnswer(point, included, "right")}>큰 수 →</button></div></div></section>;
}

function ContextVisual({ questId }: { questId: number }) {
  if (questId === 1) return <div className="context-visual context-visual--cards"><div><b>정확한 수</b><span>한 가지 값</span></div><div><b>수의 범위</b><span>여러 수 묶기</span></div><div><b>어림한 수</b><span>가까운 값</span></div></div>;
  if (questId === 4) return <div className="context-visual context-visual--table"><div className="context-visual__row context-visual__row--head"><span>표현</span><span>점</span><span>방향</span></div><div className="context-visual__row"><span>이상·이하</span><span>● 포함</span><span>기준값 쪽</span></div><div className="context-visual__row"><span>초과·미만</span><span>○ 제외</span><span>큰 수·작은 수</span></div></div>;
  if (questId === 7) return <div className="context-visual context-visual--place"><div className="context-visual__place-head"><span>천의 자리까지 반올림</span><b>바로 아래 자리 확인</b></div><div className="context-visual__place-grid"><span>천</span><span className="is-target">백</span><span>십</span><span>일</span><strong>3</strong><strong className="is-check">6</strong><strong>5</strong><strong>0</strong></div><p>목표 자리 <b>천</b> · 확인할 자리 <b>백 6</b> → 5 이상이면 올려요.</p></div>;
  if ([5, 6].includes(questId)) return <div className="context-visual context-visual--steps"><span>상황의 목적</span><ArrowRight size={15} /><strong>{questId === 5 ? "부족하지 않게" : "완전한 묶음"}</strong><ArrowRight size={15} /><b>{questId === 5 ? "올림" : "버림"}</b></div>;
  if (questId === 8) return <div className="context-visual context-visual--table"><div className="context-visual__row context-visual__row--head"><span>목적</span><span>방법</span><span>생각</span></div><div className="context-visual__row"><span>부족하면 안 됨</span><span>올림</span><span>하나 더</span></div><div className="context-visual__row"><span>완성 묶음</span><span>버림</span><span>남은 것 제외</span></div><div className="context-visual__row"><span>가장 가까움</span><span>반올림</span><span>5 이상 올림</span></div></div>;
  if ([9, 10, 11].includes(questId)) return <div className="context-visual context-visual--check"><span>① 조건/수</span><ArrowRight size={15} /><span>② 기준/자리</span><ArrowRight size={15} /><strong>③ 목적에 맞는 답</strong></div>;
  return null;
}

function QuestContextAid({ questId, hidden = false }: { questId: number; hidden?: boolean }) {
  if (hidden) return null;
  const aids: Record<number, { label: string; rule: string; note: string }> = {
    1: { label: "표현 고르기", rule: "정확 · 범위 · 어림", note: "정확히 세는지, 기준으로 나누는지, 가까운 수로 말하는지 먼저 구분해요." },
    2: { label: "채워진 점", rule: "같아도 포함", note: "이상·이하는 기준값과 같은 수도 범위 안에 넣어요." },
    3: { label: "빈 점", rule: "같으면 제외", note: "초과·미만은 기준값과 같은 수를 범위 밖에 두어요." },
    4: { label: "조건 판정", rule: "두 조건 모두", note: "‘그리고’가 있으면 한 조건씩 확인한 뒤 모두 맞는지 판단해요." },
    5: { label: "올림 판단", rule: "부족하면 안 됨", note: "모두 담거나 모두 준비해야 하면 남는 양이 있어도 하나 더 준비해요." },
    6: { label: "버림 판단", rule: "완성 묶음만", note: "남은 것이 있더라도 완성된 묶음이 아니면 세지 않아요." },
    7: { label: "반올림 판단", rule: "가장 가까운 값", note: "남기는 자리 바로 아래 숫자가 5 이상인지 확인해요." },
    8: { label: "방법 선택", rule: "목적부터 읽기", note: "부족하지 않게·완성 묶음·가까운 값 중 무엇이 필요한지 찾으세요." },
    9: { label: "요금 비교", rule: "더 높은 요금", note: "무게 요금과 크기 요금을 각각 찾고 더 높은 요금을 골라요." },
    10: { label: "문제 점검", rule: "수 · 기준 · 목적", note: "문제를 풀 수 있는 수와 어림 자리, 상황의 목적이 모두 있는지 확인해요." },
    11: { label: "종합 판정", rule: "경계값 + 목적", note: "범위는 끝값 포함 여부를, 어림은 왜 그 방법이 필요한지를 먼저 판단해요." }
  };
  const aid = aids[questId];
  return <aside className="quest-context-aid" aria-label={`${aid.label} 학습 안내`}><div className="quest-context-aid__copy"><span>{aid.label}</span><strong>{aid.rule}</strong><p>{aid.note}</p></div><ContextVisual questId={questId} /></aside>;
}

function TheoryStepStrip({ questId }: { questId: number }) {
  const steps: Record<number, [string, string, string]> = {
    1: ["상황 읽기", "정확·범위·어림 구분", "알맞은 표현 고르기"],
    2: ["기준값 찾기", "같은 수 포함", "범위 안인지 판단"],
    3: ["기준값 찾기", "같은 수 제외", "범위 안인지 판단"],
    4: ["끝점 보기", "점 모양 확인", "방향·두 조건 판단"],
    5: ["목적 읽기", "남는 양 확인", "부족하지 않게 올림"],
    6: ["목적 읽기", "완성 묶음 확인", "남은 양은 버림"],
    7: ["목표 자리 찾기", "바로 아래 자리 보기", "5 이상이면 올림"],
    8: ["상황의 목적 읽기", "올림·버림·반올림 선택", "계산 결과 점검"],
    9: ["무게 요금 찾기", "크기 요금 찾기", "높은 요금 고르기"],
    10: ["수와 단위 확인", "기준 자리·목적 확인", "답이 하나인지 점검"],
    11: ["경계·목적 읽기", "규칙 적용", "단위와 뜻 점검"]
  };
  return <div className="theory-step-strip" aria-label="문제 풀이 생각 순서"><span>생각 순서</span>{steps[questId].map((step, index) => <div key={step}><b>{index + 1}</b><strong>{step}</strong>{index < 2 && <ArrowRight size={14} />}</div>)}</div>;
}

export default function Home() {
  const reviewMode = new URLSearchParams(window.location.search).get("review") === "1";
  const storageKey = (key: string) => `${reviewMode ? "review-" : ""}curriculum-v2-${key}`;
  const [records, setRecords] = useState<Records>(() => emptyRecords());
  const [wrongNotes, setWrongNotes] = useState<WrongNote[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [screen, setScreen] = useState<Screen>(() => { const requested = new URLSearchParams(window.location.search).get("screen"); return requested === "brief" || requested === "achievements" || requested === "study" || requested === "diagnostic" || requested === "play" || requested === "boss" || requested === "boss-prep" || requested === "notes" ? requested : "map"; });
  const [activeQuestId, setActiveQuestId] = useState(() => { const value = Number(new URLSearchParams(window.location.search).get("quest")); return Number.isInteger(value) && value >= 1 && value <= quests.length ? value : 1; });
  const [activeNoteId, setActiveNoteId] = useState<string | null>(null);
  const [noteFilter, setNoteFilter] = useState<NoteFilter>("all");
  const [reviewQueue, setReviewQueue] = useState<string[]>([]);
  const [questionIndex, setQuestionIndex] = useState(() => { const value = Number(new URLSearchParams(window.location.search).get("q")); const limit = quests[activeQuestId - 1]?.questions.length ?? 1; return Number.isInteger(value) && value >= 0 && value < limit ? value : 0; });
  const [selected, setSelected] = useState<string[]>([]);
  const [submitted, setSubmitted] = useState(false);
  const [correct, setCorrect] = useState(false);
  const [attempts, setAttempts] = useState(0);
  const [correctCount, setCorrectCount] = useState(0);
  const [hints, setHints] = useState(0);
  const [startedAt, setStartedAt] = useState<number | null>(null);
  const [elapsed, setElapsed] = useState(0);
  const [lastResult, setLastResult] = useState<RecordValue | null>(null);
  const [showHint, setShowHint] = useState(false);
  const [showSolvedStamp, setShowSolvedStamp] = useState(false);
  const [unlockSequence, setUnlockSequence] = useState<UnlockSequence | null>(null);
  const [miniQueue, setMiniQueue] = useState<MiniReviewItem[]>([]);
  const [miniIndex, setMiniIndex] = useState(0);
  const [miniCorrectCount, setMiniCorrectCount] = useState(0);
  const [miniAttempts, setMiniAttempts] = useState(0);
  const [miniWeakQuestId, setMiniWeakQuestId] = useState<number | null>(null);
  const [miniReason, setMiniReason] = useState<WrongReason | null>(null);
  const [reasonProgress, setReasonProgress] = useState<ReasonProgress>(() => emptyReasonProgress());
  const [diagnosticSelected, setDiagnosticSelected] = useState("");
  const [diagnosticSubmitted, setDiagnosticSubmitted] = useState(false);

  useEffect(() => { try { const savedRecords = window.localStorage.getItem(storageKey("boundary-quest-records")); const savedNotes = window.localStorage.getItem(storageKey("boundary-wrong-notes")); const savedReasonProgress = window.localStorage.getItem(storageKey("boundary-reason-progress")); if (savedRecords) setRecords({ ...emptyRecords(), ...JSON.parse(savedRecords) }); if (savedNotes) setWrongNotes(JSON.parse(savedNotes)); if (savedReasonProgress) setReasonProgress({ ...emptyReasonProgress(), ...JSON.parse(savedReasonProgress) }); } finally { setLoaded(true); } }, []);
  useEffect(() => { if (loaded) { window.localStorage.setItem(storageKey("boundary-quest-records"), JSON.stringify(records)); window.localStorage.setItem(storageKey("boundary-wrong-notes"), JSON.stringify(wrongNotes)); window.localStorage.setItem(storageKey("boundary-reason-progress"), JSON.stringify(reasonProgress)); } }, [records, wrongNotes, reasonProgress, loaded]);
  useEffect(() => { if (screen !== "play" || !startedAt) return; const interval = window.setInterval(() => setElapsed(Math.floor((Date.now() - startedAt) / 1000)), 1000); return () => window.clearInterval(interval); }, [screen, startedAt]);

  const quest = quests[activeQuestId - 1];
  const question = quest.questions[questionIndex];
  const boss = bossChallenges[activeQuestId];
  const completedCount = quests.filter((item) => records[item.id]?.completed).length;
  const achievementCount = completedCount + (completedCount === quests.length ? 1 : 0);
  const unlocked = (id: number) => canOpenQuest(id, quests.length, records, reviewMode);
  const activeRecord = records[activeQuestId] ?? emptyRecords()[activeQuestId];
  const currentCorrect = isAnswerCorrect(question.answers, selected);

  const saveWrongNote = (selectedAnswer: string[]) => setWrongNotes((current) => { const id = noteKey(activeQuestId, questionIndex); const old = current.find((note) => note.id === id); const next: WrongNote = { ...question, id, questId: activeQuestId, questionIndex, selected: selectedAnswer, wrongCount: (old?.wrongCount ?? 0) + 1, lastWrongAt: Date.now() }; return old ? current.map((note) => note.id === id ? next : note) : [...current, next]; });
  const clearWrongNote = (questId: number, index: number) => setWrongNotes((current) => current.filter((note) => note.id !== noteKey(questId, index)));

  const openQuest = (id: number) => { if (!unlocked(id)) return; setActiveQuestId(id); setScreen("brief"); setQuestionIndex(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); };
  const startDiagnostic = () => { setDiagnosticSelected(""); setDiagnosticSubmitted(false); setScreen("diagnostic"); };
  const startQuest = () => { const now = Date.now(); setStartedAt(now); setElapsed(0); setAttempts(0); setCorrectCount(0); setHints(0); setQuestionIndex(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("play"); };
  const submitDiagnostic = () => { if (!diagnosticSelected || diagnosticSubmitted) return; const diagnosticCorrect = diagnosticSelected === diagnosticItems[activeQuestId].answer; setDiagnosticSubmitted(true); setRecords((current) => ({ ...current, [activeQuestId]: { ...(current[activeQuestId] ?? emptyRecords()[activeQuestId]), diagnosticAttempted: true, diagnosticCorrect } })); };
  const submit = () => { if (selected.length === 0) return; setAttempts((count) => count + 1); setCorrect(currentCorrect); setSubmitted(true); if (currentCorrect) { setCorrectCount((count) => count + 1); clearWrongNote(activeQuestId, questionIndex); } else saveWrongNote(selected); };
  const retry = () => { setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); };
  const nextQuestion = () => { if (questionIndex < quest.questions.length - 1) { setQuestionIndex((index) => index + 1); retry(); } else { retry(); setScreen("boss-prep"); } };
  const startBoss = () => { retry(); setScreen("boss"); };
  const submitBoss = () => { if (!selected.length) return; const bossCorrect = isAnswerCorrect(boss.question.answers, selected); setAttempts((count) => count + 1); setCorrect(bossCorrect); setSubmitted(true); if (bossCorrect) setCorrectCount((count) => count + 1); };
  const finishQuest = () => { const finalSeconds = startedAt ? Math.floor((Date.now() - startedAt) / 1000) : elapsed; const totalQuestions = quest.questions.length + 1; const accuracy = Math.round((totalQuestions / Math.max(attempts, totalQuestions)) * 100); const previous = records[activeQuestId] ?? emptyRecords()[activeQuestId]; const nextRecord: RecordValue = { best: previous.best ? Math.min(previous.best, finalSeconds) : finalSeconds, accuracy, attempts, hints, completed: true, bossCleared: true, rewardTitle: boss.rewardTitle }; setRecords((current) => ({ ...current, [activeQuestId]: nextRecord })); setLastResult(nextRecord); if (activeQuestId === quests.length) { setScreen("ending"); } else { setUnlockSequence({ from: activeQuestId, next: quests.find((item) => item.id !== activeQuestId && !records[item.id]?.completed && item.id < quests.length)?.id ?? quests.length, result: nextRecord }); setScreen("unlock"); } };
  const toggleOption = (option: string) => { if (submitted) return; if (question.multiple) setSelected((current) => current.includes(option) ? current.filter((item) => item !== option) : [...current, option]); else setSelected([option]); };
  const openNote = (note: WrongNote) => { setReviewQueue([]); setActiveNoteId(note.id); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("note-play"); };
  const reviewWeakConcept = (questId: number) => { setActiveQuestId(questId); setQuestionIndex(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("study"); };
  const filteredNotes = noteFilter === "all" ? wrongNotes : wrongNotes.filter((note) => note.questId === noteFilter);
  const startAllReview = () => { if (!filteredNotes.length) return; const queue = filteredNotes.map((note) => note.id); setReviewQueue(queue); setActiveNoteId(queue[0]); setSelected([]); setSubmitted(false); setCorrect(false); setShowSolvedStamp(false); setScreen("note-play"); };
  const startMiniReview = () => { if (!wrongNotes.length) return; const stats = Object.values(wrongNotes.reduce<Record<number, { questId: number; count: number }>>((result, note) => { result[note.questId] = { questId: note.questId, count: (result[note.questId]?.count ?? 0) + note.wrongCount }; return result; }, {})).sort((a, b) => b.count - a.count); const weakQuestId = stats[0]?.questId; if (!weakQuestId) return; const queue = buildMiniReviewQueue(wrongNotes, weakQuestId); if (queue.length < 5) return; setActiveQuestId(weakQuestId); setMiniWeakQuestId(weakQuestId); setMiniReason(null); setMiniQueue(queue); setMiniIndex(0); setMiniCorrectCount(0); setMiniAttempts(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("mini-review"); };
  const startReasonReview = (reason: WrongReason) => { const queue = buildReasonReviewQueue(wrongNotes, reason); const weakQuestId = queue[0]?.questId; if (!weakQuestId || queue.length < 5) return; setReasonProgress((current) => ({ ...current, [reason]: { ...current[reason], started: current[reason].started + 1 } })); setActiveQuestId(weakQuestId); setMiniWeakQuestId(weakQuestId); setMiniReason(reason); setMiniQueue(queue); setMiniIndex(0); setMiniCorrectCount(0); setMiniAttempts(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("mini-review"); };
  const submitMiniReview = () => { const item = miniQueue[miniIndex]; if (!item || !selected.length) return; const itemCorrect = isAnswerCorrect(item.answers, selected); setMiniAttempts((count) => count + 1); setCorrect(itemCorrect); setSubmitted(true); if (itemCorrect) setMiniCorrectCount((count) => count + 1); };
  const nextMiniReview = () => { if (miniIndex < miniQueue.length - 1) { setMiniIndex((index) => index + 1); retry(); } else { if (miniReason && miniCorrectCount >= 4) setReasonProgress((current) => ({ ...current, [miniReason]: { ...current[miniReason], completed: current[miniReason].completed + 1 } })); setScreen("mini-result"); } };
  const playSolvedFeedback = () => { if ("vibrate" in navigator) navigator.vibrate?.([35, 22, 65]); try { const audio = new AudioContext(); const now = audio.currentTime; [660, 880].forEach((frequency, index) => { const oscillator = audio.createOscillator(); const gain = audio.createGain(); oscillator.type = "triangle"; oscillator.frequency.setValueAtTime(frequency, now + index * 0.11); gain.gain.setValueAtTime(0.0001, now + index * 0.11); gain.gain.exponentialRampToValueAtTime(0.075, now + index * 0.11 + 0.015); gain.gain.exponentialRampToValueAtTime(0.0001, now + index * 0.11 + 0.22); oscillator.connect(gain).connect(audio.destination); oscillator.start(now + index * 0.11); oscillator.stop(now + index * 0.11 + 0.24); }); window.setTimeout(() => audio.close(), 500); } catch { /* browser sound is optional */ } };
  const finishNote = (note: WrongNote) => { clearWrongNote(note.questId, note.questionIndex); setCorrect(true); setSubmitted(true); setShowSolvedStamp(true); playSolvedFeedback(); window.setTimeout(() => { setShowSolvedStamp(false); const remaining = reviewQueue.filter((id) => id !== note.id); if (remaining.length) { setReviewQueue(remaining); setActiveNoteId(remaining[0]); setSelected([]); setSubmitted(false); setCorrect(false); } else { setReviewQueue([]); setScreen("notes"); } }, 1250); };

  if (screen === "brief") return <BriefScreen quest={quest} record={activeRecord} noteCount={wrongNotes.length} onBack={() => setScreen("map")} onNotes={() => setScreen("notes")} onStudy={() => setScreen("study")} onStart={startDiagnostic} />;
  if (screen === "diagnostic") return <DiagnosticScreen quest={quest} item={diagnosticItems[activeQuestId]} selected={diagnosticSelected} submitted={diagnosticSubmitted} onBack={() => setScreen("brief")} onSelect={setDiagnosticSelected} onSubmit={submitDiagnostic} onStart={startQuest} />;
  if (screen === "play") return <PlayScreen quest={quest} question={question} questionIndex={questionIndex} selected={selected} submitted={submitted} correct={correct} elapsed={elapsed} attempts={attempts} hints={hints} showHint={showHint} noteCount={wrongNotes.length} onBack={() => setScreen("map")} onNotes={() => setScreen("notes")} onStudy={() => setScreen("study")} onToggle={toggleOption} onSubmit={submit} onRetry={retry} onNext={nextQuestion} onHint={() => { setShowHint((value) => !value); if (!showHint) setHints((value) => value + 1); }} />;
  if (screen === "boss-prep") return <BossPrepScreen quest={quest} onBack={() => setScreen("map")} onStart={startBoss} />;
  if (screen === "boss") return <BossScreen quest={quest} boss={boss} selected={selected} submitted={submitted} correct={correct} elapsed={elapsed} attempts={attempts} onBack={() => setScreen("map")} onToggle={toggleOption} onSubmit={submitBoss} onRetry={retry} onClear={() => { retry(); setScreen("boss-clear"); }} />;
  if (screen === "boss-clear") return <BossClearScreen quest={quest} boss={boss} onContinue={finishQuest} onMap={() => setScreen("map")} />;
  if (screen === "unlock" && unlockSequence) return <UnlockScreen sequence={unlockSequence} noteCount={wrongNotes.length} onMap={() => { setActiveQuestId(unlockSequence.next ?? unlockSequence.from); setUnlockSequence(null); setScreen("map"); }} onNext={() => { if (!unlockSequence.next || !unlocked(unlockSequence.next)) { setUnlockSequence(null); setScreen("map"); return; } setActiveQuestId(unlockSequence.next); setUnlockSequence(null); setScreen("brief"); }} onAchievements={() => setScreen("achievements")} />;
  if (screen === "ending") return <FinalEndingScreen records={records} noteCount={wrongNotes.length} onMap={() => setScreen("map")} onAchievements={() => setScreen("achievements")} />;
  if (screen === "achievements") return <AchievementScreen records={records} noteCount={wrongNotes.length} onMap={() => setScreen("map")} />;
  if (screen === "study") return <StudyNotesScreen activeQuestId={activeQuestId} onMap={() => setScreen("map")} onQuest={(questId: number) => { setActiveQuestId(questId); setScreen("brief"); }} />;
  if (screen === "result" && lastResult) return <ResultScreen quest={quest} result={lastResult} noteCount={wrongNotes.length} onMap={() => { const nextId = Math.min(quests.length, activeQuestId + 1); setActiveQuestId(nextId); setScreen("map"); }} onNotes={() => setScreen("notes")} onNext={() => { const nextId = Math.min(quests.length, activeQuestId + 1); setActiveQuestId(nextId); setScreen(unlocked(nextId) ? "brief" : "map"); }} />;
  if (screen === "notes") return <MistakeBookScreen notes={wrongNotes} filter={noteFilter} reasonProgress={reasonProgress} onFilter={setNoteFilter} onMap={() => setScreen("map")} onStudy={() => setScreen("study")} onPractice={openNote} onAllPractice={startAllReview} onMiniReview={startMiniReview} onReviewConcept={reviewWeakConcept} onReviewReason={startReasonReview} />;
  if (screen === "note-play") { const note = wrongNotes.find((item) => item.id === activeNoteId); if (note) return <MistakePracticeScreen note={note} selected={selected} submitted={submitted} correct={correct} showSolvedStamp={showSolvedStamp} onBack={() => setScreen("notes")} onToggle={(option) => { if (!submitted) setSelected((current) => note.multiple ? current.includes(option) ? current.filter((item) => item !== option) : [...current, option] : [option]); }} onSubmit={() => { if (isAnswerCorrect(note.answers, selected)) finishNote(note); else { setCorrect(false); setSubmitted(true); saveNoteRetry(note, selected, setWrongNotes); } }} onRetry={retry} />; }
  if (screen === "mini-review" && miniQueue[miniIndex]) return <MiniReviewScreen queue={miniQueue} weakQuestId={miniWeakQuestId ?? activeQuestId} index={miniIndex} selected={selected} submitted={submitted} correct={correct} attempts={miniAttempts} onBack={() => setScreen("notes")} onToggle={(option) => { if (submitted) return; const item = miniQueue[miniIndex]; setSelected((current) => item.multiple ? current.includes(option) ? current.filter((choice) => choice !== option) : [...current, option] : [option]); }} onSubmit={submitMiniReview} onRetry={retry} onNext={nextMiniReview} />;
  if (screen === "mini-result" && miniWeakQuestId) return <MiniReviewResultScreen quest={quests[miniWeakQuestId - 1]} correctCount={miniCorrectCount} attempts={miniAttempts} onNotes={() => setScreen("notes")} onRestart={startMiniReview} />;
  return <MapScreen reviewMode={reviewMode} records={records} completedCount={completedCount} achievementCount={achievementCount} activeQuestId={activeQuestId} wrongCount={wrongNotes.length} onOpen={openQuest} onNotes={() => setScreen("notes")} onStudy={() => setScreen("study")} onAchievements={() => setScreen("achievements")} />;
}

function saveNoteRetry(note: WrongNote, selectedAnswer: string[], setWrongNotes: React.Dispatch<React.SetStateAction<WrongNote[]>>) { setWrongNotes((current) => current.map((item) => item.id === note.id ? { ...item, selected: selectedAnswer, wrongCount: item.wrongCount + 1, lastWrongAt: Date.now() } : item)); }

function Header({ onMap, onNotes, onStudy, onAchievements, noteCount = 0, title = "경계의 성", focus = "01 · 단원 도입" }: { onMap?: () => void; onNotes?: () => void; onStudy?: () => void; onAchievements?: () => void; noteCount?: number; title?: string; focus?: string }) {
  return <header className="quest-header"><button type="button" className="quest-brand" onClick={onMap}><span className="quest-brand__mark"><ShieldCheck size={19} /><i>문</i></span><span><small>1단원 · 수의 범위와 어림하기</small><strong>경계의 성</strong><em>{title}</em></span></button><div className="quest-header__center"><span>지금 열 관문</span><ChevronRight size={14} /><b>{focus}</b></div><div className="quest-header__actions">{onAchievements && <button type="button" className="achievement-header-button" onClick={onAchievements}><Trophy size={16} /> 업적</button>}{onStudy && <button type="button" className="study-header-button" onClick={onStudy}><BookOpen size={16} /> 요점 노트</button>}{onNotes && <button type="button" className="notes-header-button" onClick={onNotes}><BookOpenCheck size={16} /> 오답 노트 <b>{noteCount}</b></button>}<div className="quest-header__profile"><span>나의 기록</span><strong>J</strong></div></div></header>;
}

/** Design: neo-brutalist badge vault — ink outline, offset shadow, primary color blocks, completion as a collectible stamp. */
function AchievementScreen({ records, noteCount, onMap }: { records: Records; noteCount: number; onMap: () => void }) {
  const completed = quests.filter((item) => records[item.id]?.completed);
  const totalBest = completed.reduce((total, item) => total + (records[item.id].best ?? 0), 0);
  const averageAccuracy = completed.length ? Math.round(completed.reduce((total, item) => total + records[item.id].accuracy, 0) / completed.length) : 0;
  const fullClear = completed.length === quests.length;
  return <main className="quest-app">
    <Header onMap={onMap} title="업적 보관소" focus={`${completed.length} / ${quests.length} 관문 통과`} />
    <section className="achievement-page">
      <div className="achievement-hero"><div><p className="quest-kicker">획득한 관문 인장</p><h1>배지를 모아<br /><em>성의 기록을 남겨요.</em></h1><p>각 관문을 통과하면 인장이 보관됩니다. 최고 기록과 정확도를 확인하고, 비어 있는 인장도 다음 도전에서 채워 보세요.</p><div className="achievement-summary"><span><Trophy size={18} /><b>{completed.length}</b> / {quests.length} 획득</span><span><Target size={18} /><b>{averageAccuracy}%</b> 평균 정확도</span><span><Clock3 size={18} /><b>{completed.length ? formatTime(totalBest) : "--:--"}</b> 최고 기록 합계</span></div></div><div className={`achievement-hero__badge ${fullClear ? "achievement-hero__badge--crowned" : ""}`}><QuestArt id={11} eager /><span>{fullClear ? "성 복구 업적" : "다음 배지를 향해"}</span></div></div>
      <div className="achievement-grid">{quests.map((item) => {
        const record = records[item.id];
        const earned = record?.completed;
        return <article key={item.id} className={`achievement-card achievement-card--${item.tone} ${earned ? "achievement-card--earned" : "achievement-card--locked"}`}><div className="achievement-card__seal"><QuestArt id={item.id} /></div><div className="achievement-card__title"><span>관문 {String(item.id).padStart(2, "0")}</span><h2>{earned ? item.title : "봉인된 인장"}</h2><p>{earned ? item.concept : "앞 관문을 통과하면 이 배지가 열립니다."}</p></div><div className="achievement-card__record">{earned ? <div className="achievement-card__record-list"><span><Crown size={14} /> 칭호 <b>{record.rewardTitle ?? "관문 개척자"}</b></span><span><Clock3 size={14} /> 최고 <b>{formatTime(record.best ?? 0)}</b></span><span><Target size={14} /> 정확도 <b>{record.accuracy}%</b></span><span><RotateCcw size={14} /> 최근 시도 <b>{record.attempts}회</b></span></div> : <span className="achievement-card__empty"><Lock size={14} /> 미획득</span>}</div><i className="achievement-card__stamp">{earned ? "획득" : "봉인"}</i></article>;
      })}</div>
      <div className="achievement-footer"><div><Crown size={22} /><span><b>{fullClear ? "경계의 성 복구 완료" : `마지막 업적까지 ${quests.length - completed.length}개 관문 남음`}</b><small>{noteCount ? `오답 노트에 ${noteCount}문제가 있어요. 복습 후 더 단단하게 통과해 보세요.` : "오답 노트가 비어 있어요. 정확한 학습 기록입니다."}</small></span></div><button type="button" className="map-button" onClick={onMap}>퀘스트 지도로 <ArrowRight size={17} /></button></div>
    </section>
  </main>;
}

/** Design: a staged, cinematic brutalist finale that preserves the app's stamp-and-print language over game art. */
function FinalEndingScreen({ records, noteCount, onMap, onAchievements }: { records: Records; noteCount: number; onMap: () => void; onAchievements: () => void }) {
  const [phase, setPhase] = useState(0);
  const completed = quests.filter((item) => records[item.id]?.completed);
  const totalBest = completed.reduce((total, item) => total + (records[item.id].best ?? 0), 0);
  const averageAccuracy = completed.length ? Math.round(completed.reduce((total, item) => total + records[item.id].accuracy, 0) / completed.length) : 0;
  useEffect(() => { const timers = [window.setTimeout(() => setPhase(1), 480), window.setTimeout(() => setPhase(2), 1280), window.setTimeout(() => setPhase(3), 2180)]; return () => timers.forEach((timer) => window.clearTimeout(timer)); }, []);
  const confetti = Array.from({ length: 38 }, (_, index) => ({ id: index, x: (index * 37) % 100, delay: (index % 9) * 0.13, duration: 1.7 + (index % 5) * 0.22, rotate: (index * 53) % 360 }));
  return <main className="quest-app"><Header onMap={phase >= 3 ? onMap : undefined} onAchievements={phase >= 3 ? onAchievements : undefined} noteCount={noteCount} title="경계의 성" focus="11관문 · 최종 통과" /><section className={`final-ending final-ending--phase-${phase}`}><div className="final-ending__veil" /><div className="final-ending__confetti" aria-hidden="true">{confetti.map((piece) => <i key={piece.id} style={{ "--x": `${piece.x}%`, "--delay": `${piece.delay}s`, "--duration": `${piece.duration}s`, "--spin": `${piece.rotate}deg` } as CSSProperties} />)}</div><div className="final-ending__content"><p className="quest-kicker">최종 관문 통과 · 11 / 11</p><CastleArt /><h1>경계의 성이<br /><em>다시 빛납니다.</em></h1><p>11개의 관문과 {quests.reduce((total, item) => total + item.questions.length, 0)}문항을 끝까지 탐험했어요. 숫자의 범위와 어림하기 지도를 완성했습니다.</p><RuleRecap questId={11} /><div className="final-ending__records"><span><Trophy size={18} /><b>{completed.length}</b>개 관문</span><span><Target size={18} /><b>{averageAccuracy}%</b> 평균 정확도</span><span><Clock3 size={18} /><b>{formatTime(totalBest)}</b> 최고 기록 합계</span></div><div className="final-ending__actions"><button type="button" className="map-button" onClick={onAchievements} disabled={phase < 3}>업적 보관소 <Trophy size={17} /></button><button type="button" className="next-quest final-ending__map-button" onClick={onMap} disabled={phase < 3}>복구된 지도 보기 <ArrowRight size={17} /></button></div></div></section></main>;
}

function StudyConceptVisual({ note }: { note: StudyNote }) {
  if (note.questId === 9) return <QuestionVisualCard visual={parcelTable} />;
  if (note.questId === 2) return <figure className="study-visual study-visual--numberline"><figcaption><span>그림으로 비교</span><b>이상 · 이하</b></figcaption><div className="study-visual__dual"><div><strong>120 이상</strong><svg viewBox="0 0 620 86" role="img" aria-label="120 이상 수직선"><defs><marker id="study-arrow-gte" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto-start-reverse"><path d="M1,1 L11,6 L1,11 Z" fill="currentColor" /></marker></defs><line x1="48" y1="35" x2="572" y2="35" className="study-visual__axis" /><line x1="315" y1="35" x2="562" y2="35" className="study-visual__range" markerEnd="url(#study-arrow-gte)" /><circle cx="315" cy="35" r="10" className="study-visual__point study-visual__point--closed" /><text x="315" y="70" textAnchor="middle" className="study-visual__number">120 ● 포함</text></svg></div><div><strong>120 이하</strong><svg viewBox="0 0 620 86" role="img" aria-label="120 이하 수직선"><defs><marker id="study-arrow-lte" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto-start-reverse"><path d="M1,1 L11,6 L1,11 Z" fill="currentColor" /></marker></defs><line x1="48" y1="35" x2="572" y2="35" className="study-visual__axis" /><line x1="305" y1="35" x2="58" y2="35" className="study-visual__range" markerEnd="url(#study-arrow-lte)" /><circle cx="305" cy="35" r="10" className="study-visual__point study-visual__point--closed" /><text x="305" y="70" textAnchor="middle" className="study-visual__number">120 ● 포함</text></svg></div></div><p><span className="study-visual__closed">●</span> 이상·이하는 기준값을 포함하고, 범위선은 점에서 시작해 화살표 방향으로 이어져요.</p></figure>;
  if ([2, 3, 4].includes(note.questId)) {
    const isInclude = note.questId === 2;
    const isLess = note.questId === 3;
    const label = note.questId === 2 ? "120 이상" : note.questId === 3 ? "85 미만" : "40 초과";
    const values = note.questId === 2 ? [118, 119, 120, 121, 122] : note.questId === 3 ? [83, 84, 85, 86, 87] : [38, 39, 40, 41, 42];
    const boundaryIndex = values.findIndex((value) => value === (isInclude ? 120 : isLess ? 85 : 40));
    const boundaryX = 80 + boundaryIndex * 115;
    const rangeEnd = isLess ? 58 : 562;
    return <figure className="study-visual study-visual--numberline"><figcaption><span>그림으로 확인</span><b>{label}</b></figcaption><svg viewBox="0 0 620 142" role="img" aria-label={`${label}을 나타낸 수직선`}><defs><marker id={`study-arrow-${note.questId}`} viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto-start-reverse"><path d="M1,1 L11,6 L1,11 Z" fill="currentColor" /></marker></defs><line x1="48" y1="62" x2="572" y2="62" className="study-visual__axis" /><line x1={boundaryX} y1="62" x2={rangeEnd} y2="62" className="study-visual__range" markerEnd={`url(#study-arrow-${note.questId})`} />{values.map((value, index) => { const cx = 80 + index * 115; const boundary = index === boundaryIndex; return <g key={value}><line x1={cx} y1="51" x2={cx} y2="73" className="study-visual__tick" /><text x={cx} y="103" textAnchor="middle" className="study-visual__number">{value}</text>{boundary && <circle cx={cx} cy="62" r="10" className={isInclude ? "study-visual__point study-visual__point--closed" : "study-visual__point"} />}</g>})}</svg><p><span className="study-visual__closed">●</span> 포함 <span className="study-visual__open">○</span> 제외 · 범위선은 기준점에서 시작해 화살표 방향으로 이어져요.</p></figure>;
  }
  if ([5, 6, 7].includes(note.questId)) {
    const kind = note.questId === 5 ? "올림" : note.questId === 6 ? "버림" : "반올림";
    return <figure className="study-visual study-visual--cards"><figcaption><span>상황의 목적을 그림으로</span><b>{kind}</b></figcaption><div className="study-visual__cards"><div className="study-visual__card study-visual__card--a"><strong>{note.questId === 5 ? "83개" : note.questId === 6 ? "764cm" : "3,650"}</strong><small>주어진 양</small></div><div className="study-visual__arrow"><ArrowRight size={22} /></div><div className="study-visual__card study-visual__card--b"><strong>{note.questId === 5 ? "9상자" : note.questId === 6 ? "76묶음" : "4,000"}</strong><small>{note.questId === 5 ? "부족하지 않게" : note.questId === 6 ? "완전한 묶음만" : "가장 가까운 값"}</small></div></div><p>{note.questId === 5 ? "8상자는 부족하므로 한 묶음 더 준비해요." : note.questId === 6 ? "남은 4cm는 완전한 묶음이 아니에요." : "바로 아래 자리 6이 5 이상이라 올려요."}</p></figure>;
  }
  return <figure className="study-visual study-visual--flow"><figcaption><span>판단 순서</span><b>읽고 → 확인하고 → 선택하기</b></figcaption><div><span>상황의 목적</span><ArrowRight size={18} /><span>기준값·자리</span><ArrowRight size={18} /><strong>{note.questId === 1 ? "범위" : note.questId === 8 ? "알맞은 방법" : "설명 가능한 답"}</strong></div></figure>;
}

function StudyNotesScreen({ activeQuestId, onMap, onQuest }: { activeQuestId: number; onMap: () => void; onQuest: (questId: number) => void }) {
  const [selectedId, setSelectedId] = useState(activeQuestId);
  const selected = studyNotes.find((note) => note.questId === selectedId) ?? unitStudyNote;
  return <main className="quest-app"><Header onMap={onMap} title="요점 노트" focus="학습지형 복습 공간" /><section className="study-page"><div className="study-hero"><div><p className="quest-kicker">1단원 핵심 정리 · 읽기 → 판단 → 적용</p><h1>요점 노트로<br /><em>규칙을 손에 넣어요.</em></h1><p>문제를 풀기 전에 읽어도 좋고, 틀린 뒤 다시 확인해도 좋아요. 한 장씩 넘기며 핵심 규칙과 대표 예시를 정리해 보세요.</p></div><QuestArt id={1} className="study-hero-scene" eager /></div><div className="study-layout"><nav className="study-index" aria-label="관문별 요점 노트"><div className="study-index__title"><span>학습지 목차</span><b>{studyNotes.length}장</b></div>{studyNotes.map((note) => <button type="button" key={note.questId} className={`study-index__item study-index__item--${note.tone} ${selected.questId === note.questId ? "is-selected" : ""}`} onClick={() => setSelectedId(note.questId)}><span>{String(note.questId).padStart(2, "0")}</span><div><b>{note.label}</b><strong>{note.title}</strong></div><ChevronRight size={16} /></button>)}</nav><article className={`study-sheet study-sheet--${selected.tone}`}><header className="study-sheet__header"><div><span>관문 {String(selected.questId).padStart(2, "0")} · {selected.label}</span><h2>{selected.title}</h2></div><div className="study-sheet__badge">핵심</div></header><div className="study-sheet__lead"><Lightbulb size={23} /><strong>{selected.oneLine}</strong></div><StudyConceptVisual note={selected} /><div className="study-sheet__grid"><section><span className="study-label">기억할 규칙</span><div className="study-rules">{selected.rules.map((rule, index) => <p key={rule}><b>{index + 1}</b>{rule}</p>)}</div></section><section className="study-example"><span className="study-label">대표 예시</span><p>{selected.example}</p></section></div><section className="study-check"><div><span className="study-label">나만의 확인 문장</span><h3>{selected.check}</h3></div><div className="study-check__line" aria-hidden="true" /></section><aside className="study-mistake"><AlertTriangle size={18} /><div><span>자주 하는 실수</span><p>{selected.mistake}</p></div></aside><footer className="study-sheet__footer"><button type="button" className="back-link" onClick={onMap}><ArrowLeft size={15} /> 퀘스트 맵으로</button>{selected.questId < quests.length && <button type="button" className="next-quest" onClick={() => setSelectedId(selected.questId + 1)}>다음 요점 <ArrowRight size={16} /></button>}{selected.questId === quests.length && <button type="button" className="next-quest" onClick={() => onQuest(1)}>1관문 문제로 <ArrowRight size={16} /></button>}</footer></article></div><div className="study-bottom"><span><BookOpenCheck size={16} /> 틀린 문제의 관문 노트를 먼저 읽어 보세요.</span><button type="button" className="map-button" onClick={() => onQuest(selected.questId)}>이 개념 문제 풀기 <ArrowRight size={16} /></button></div></section></main>;
}

const questArtPath = (id: number) => `/art/quest-${String(id).padStart(2, "0")}-v1.webp`;
function QuestArt({ id, className = "", eager = false }: { id: number; className?: string; eager?: boolean }) {
  return <img className={`quest-art ${className}`} src={questArtPath(id)} alt={`${quests[id - 1].title} 모험 장소`} width={960} height={640} loading={eager ? "eager" : "lazy"} decoding="async" />;
}
function CastleArt() {
  return <img src="/art/castle-hero-v1.webp" alt="푸른 지붕과 황금 깃발이 빛나는 경계의 성" className="castle-art" width={1200} height={800} fetchPriority="high" />;
}

function MapScreen({ reviewMode, records, completedCount, achievementCount, activeQuestId, wrongCount, onOpen, onNotes, onStudy, onAchievements }: { reviewMode: boolean; records: Records; completedCount: number; achievementCount: number; activeQuestId: number; wrongCount: number; onOpen: (id: number) => void; onNotes: () => void; onStudy: () => void; onAchievements: () => void }) {
  const activeQuest = quests[activeQuestId - 1];
  const totalQuestions = quests.reduce((total, item) => total + item.questions.length, 0);
  return <main className="quest-app"><Header onNotes={onNotes} onStudy={onStudy} onAchievements={onAchievements} noteCount={wrongCount} focus={`${String(activeQuest.id).padStart(2, "0")} · ${activeQuest.place}`} />
    <section className="adventure-page">
      <div className="adventure-intro"><span className="adventure-eyebrow"><Sparkles size={16} /> 수학으로 떠나는 작은 모험</span><span>5학년 2학기 · 1단원</span></div>
      <section className="adventure-hero">
        <div><span className="hero-chip">수의 범위와 어림하기</span><h1>한 문제씩, 한 걸음씩.<br /><em>경계의 성으로 출발!</em></h1><p>숫자의 비밀을 풀고 11개의 관문을 탐험해요.<br />오늘도 새로운 발견이 기다리고 있어요.</p><button className="start-quest" onClick={() => onOpen(activeQuest.id)}>관문 {String(activeQuest.id).padStart(2, "0")} 도전하기 <ArrowRight size={19} /></button></div>
        <div className="adventure-art"><CastleArt /><span><Flag size={15} /> 우리의 목적지, 경계의 성</span></div>
      </section>
      <div className="adventure-stats">
        <div className="adventure-progress"><span className="stat-icon"><Flag size={21}/></span><div><span>나의 탐험 기록</span><strong>{completedCount}<small> / 11 관문</small></strong></div><div className="adventure-progress__track" role="progressbar" aria-label="관문 진행률" aria-valuenow={completedCount} aria-valuemin={0} aria-valuemax={11}><i style={{width:`${completedCount / 11 * 100}%`}} /></div></div>
        <button onClick={onAchievements}><span className="stat-icon stat-icon--gold"><Trophy size={21}/></span><span>모은 업적 <strong>{achievementCount}</strong></span><ChevronRight size={18}/></button>
        <button onClick={onStudy}><span className="stat-icon stat-icon--purple"><BookOpen size={21}/></span><span>잠깐, 개념 복습!</span><ChevronRight size={18}/></button>
      </div>
      <div className="adventure-section-title"><div><span className="adventure-eyebrow">YOUR ADVENTURE</span><h2>어느 관문으로 떠나볼까요?</h2></div><span>11개 관문 · {totalQuestions}문항</span></div>
      <div className="adventure-grid">{quests.map((item) => {
        const done = records[item.id]?.completed;
        const locked = !canOpenQuest(item.id, quests.length, records, reviewMode);
        const current = item.id === activeQuestId && !done;
        return <button key={item.id} disabled={locked} onClick={() => onOpen(item.id)} className={`adventure-gate adventure-gate--${item.tone} ${current ? "is-current" : ""} ${done ? "is-done" : ""}`}>
          <span className="adventure-gate__top"><span>STAGE {String(item.id).padStart(2,"0")}</span><span className="adventure-gate__state">{locked ? <><Lock size={12}/> 잠김</> : done ? <><Check size={13}/> 완료</> : current ? "지금 도전" : "도전 가능"}</span></span>
          <QuestArt id={item.id} className="adventure-gate__art" /><span className="adventure-gate__body"><span><strong>{item.place}</strong><span>{item.title}</span></span><ChevronRight className="adventure-gate__arrow" size={20}/></span>
          <span className="adventure-gate__footer"><span>{item.questions.length}문항</span><span>{locked ? "1~10관문을 모두 완료하면 열려요" : item.concept}</span></span>
        </button>;
      })}<div className="adventure-finish"><QuestArt id={11} /><strong>모험 끝에 만날 나!</strong><span>관문을 하나씩 지나며<br/>수학 자신감을 모아보세요.</span></div></div>
      <div className="adventure-bottom"><ShieldCheck size={17}/><span>서두르지 않아도 괜찮아요. 이해하며 한 걸음씩 나아가요.</span></div>
    </section>
  </main>;
}

function BriefScreen({ quest, record, noteCount, onBack, onNotes, onStudy, onStart }: { quest: Quest; record: RecordValue; noteCount: number; onBack: () => void; onNotes: () => void; onStudy: () => void; onStart: () => void }) {
  return <main className="quest-app"><Header onMap={onBack} onNotes={onNotes} onStudy={onStudy} noteCount={noteCount} focus={`${String(quest.id).padStart(2, "0")} · ${quest.place}`} /><section className="brief-page"><div className={`brief-visual brief-visual--${quest.tone}`}><div className="brief-scene-heading"><span>STAGE {String(quest.id).padStart(2, "0")}</span><b>{quest.place}</b></div><QuestArt id={quest.id} className="brief-scene" eager /><p className="brief-scene-caption">{quest.title}<span>이곳에서 다음 모험이 시작돼요</span></p></div><div className="brief-content"><button type="button" className="back-link" onClick={onBack}><ArrowLeft size={15} /> 퀘스트 맵으로</button><p className="quest-kicker">관문 {String(quest.id).padStart(2, "0")} · {quest.gate}</p><h1>{quest.title}</h1><p className="brief-summary">{quest.summary}</p><div className="brief-theory"><BookOpen size={19} /><div><span>이번 관문에서 알아야 할 것</span><strong>{quest.concept}</strong><p>{quest.theory}</p></div></div><div className="brief-rule"><Lightbulb size={17} /><span>{quest.questions.length}문항을 정확하게 통과하면 다음 관문의 봉인이 풀립니다.</span></div><button type="button" className="start-quest" onClick={onStart}>관문 도전 시작 <ArrowRight size={18} /></button>{record.completed && <div className="previous-record"><span>지난 기록</span><b>{formatTime(record.last ?? 0)}</b><small>최고 {formatTime(record.best ?? 0)} · 정확도 {record.accuracy}%</small></div>}</div></section></main>;
}

function DiagnosticScreen({ quest, item, selected, submitted, onBack, onSelect, onSubmit, onStart }: { quest: Quest; item: DiagnosticItem; selected: string; submitted: boolean; onBack: () => void; onSelect: (value: string) => void; onSubmit: () => void; onStart: () => void }) {
  const correct = selected === item.answer;
  return <main className="quest-app"><Header onMap={onBack} title="시작 전 한 문제" focus={`관문 ${String(quest.id).padStart(2, "0")} · 시작 확인`} /><section className={`diagnostic-page diagnostic-page--${quest.tone}`}><div className="diagnostic-card"><div className="diagnostic-card__top"><span className="diagnostic-card__status">관문 {String(quest.id).padStart(2, "0")} · 시작 전 한 문제</span><button type="button" className="diagnostic-card__skip" onClick={onBack}>나중에 풀기</button></div><div className="diagnostic-question"><span>가볍게 생각해 봐요</span><p className="diagnostic-intro">처음 보는 말이 있어도 괜찮아요. 답을 고르면 예시와 함께 뜻을 알려드려요. 시간 제한은 없어요.</p><h1>{item.prompt}</h1>{item.numberLine && <NumberLineDiagram model={item.numberLine} />}<div className="quest-options">{item.options.map((option, index) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected === option ? "quest-option--selected" : ""} ${submitted && option === item.answer ? "quest-option--correct" : ""} ${submitted && selected === option && option !== item.answer ? "quest-option--wrong" : ""}`} onClick={() => onSelect(option)}><span>{String.fromCharCode(65 + index)}</span><strong>{option}</strong>{submitted && option === item.answer && <Check size={16} />}</button>)}</div></div>{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <Lightbulb size={18} />}</span><div><strong>{correct ? "맞아요! 왜 그런지 함께 볼까요?" : "괜찮아요. 예시로 함께 알아봐요."}</strong><p>{item.rule}</p></div></div>}<div className="diagnostic-actions">{!submitted ? <button type="button" className="answer-action" disabled={!selected} onClick={onSubmit}>답과 설명 보기 <ArrowRight size={16} /></button> : <button type="button" className="next-quest" onClick={onStart}>이제 문제 풀러 가기 <ArrowRight size={16} /></button>}</div></div></section></main>;
}

function PlayScreen({ quest, question, questionIndex, selected, submitted, correct, elapsed, attempts, hints, showHint, noteCount, onBack, onNotes, onStudy, onToggle, onSubmit, onRetry, onNext, onHint }: { quest: Quest; question: QuestQuestion; questionIndex: number; selected: string[]; submitted: boolean; correct: boolean; elapsed: number; attempts: number; hints: number; showHint: boolean; noteCount: number; onBack: () => void; onNotes: () => void; onStudy: () => void; onToggle: (option: string) => void; onSubmit: () => void; onRetry: () => void; onNext: () => void; onHint: () => void }) {
  const isFinalQuestion = questionIndex === quest.questions.length - 1;
  return <main className="quest-app"><Header onMap={onBack} onNotes={onNotes} onStudy={onStudy} noteCount={noteCount} title={quest.title} focus={`${String(quest.id).padStart(2, "0")} · ${question.category} ${questionIndex + 1}/${quest.questions.length}`} /><div className="play-layout"><aside className="play-rail"><div className="play-rail__stamp">관문 장부 · 통과 기록</div><QuestArt id={quest.id} className="rail-scene" eager /><p className="quest-kicker">차시 {String(quest.id).padStart(2, "0")}</p><h1>{quest.place}<br /><em>관문</em></h1><p>{quest.concept}</p><div className="rail-time"><Clock3 size={16} /><span>경과 시간</span><strong>{formatTime(elapsed)}</strong></div><div className="rail-steps">{quest.questions.map((item, index) => <div key={index} className={index < questionIndex ? "rail-step rail-step--done" : index === questionIndex ? "rail-step rail-step--current" : "rail-step"}><span>{index < questionIndex ? <Check size={12} /> : index + 1}</span><b>{index === questionIndex ? item.category : index < questionIndex ? "통과" : item.category}</b></div>)}</div><div className="rail-record"><span>이번 시도</span><strong>{attempts}회</strong><small>힌트 {hints}회</small></div></aside><section className="play-main"><div className="question-sheet"><div className="sheet-header"><span className={`quest-tag quest-tag--${quest.tone}`}>{quest.concept}</span><span className="sheet-status">{question.category} · 문제 {questionIndex + 1}</span></div><h3>{question.prompt}</h3><TheoryStepStrip questId={quest.id} /><QuestContextAid questId={quest.id} hidden={question.category !== "오개념 교정" || Boolean(question.numberLine || question.visual || question.interactiveNumberLine)} />{question.visual && <QuestionVisualCard visual={question.visual} selected={selected} onSelect={onToggle} />}{question.numberLine && <NumberLineDiagram model={question.numberLine} />}{question.interactiveNumberLine && <InteractiveNumberLine model={question.interactiveNumberLine} value={selected[0] ?? ""} onChange={onToggle} />}{question.multiple && <p className="multi-note">정답을 모두 선택하세요.</p>}{question.input ? <label className="direct-answer"><span>숫자로 답을 입력하세요</span><input type="text" inputMode="decimal" value={selected[0] ?? ""} disabled={submitted} onChange={(event) => onToggle(event.target.value)} placeholder="정답 입력" aria-label="정답 입력" /></label> : <div className="quest-options">{question.options.map((option, index) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected.includes(option) ? "quest-option--selected" : ""} ${submitted && question.answers.includes(option) ? "quest-option--correct" : ""} ${submitted && selected.includes(option) && !question.answers.includes(option) ? "quest-option--wrong" : ""}`} onClick={() => onToggle(option)}><span>{String.fromCharCode(65 + index)}</span><strong>{option}</strong>{selected.includes(option) && !submitted && <Check size={16} />}{submitted && question.answers.includes(option) && <Check size={16} />}{submitted && selected.includes(option) && !question.answers.includes(option) && <X size={16} />}</button>)}</div>}<div className="sheet-actions"><button type="button" className="hint-action" onClick={onHint}><Lightbulb size={16} /> 힌트 {hints > 0 ? `${hints}회` : "보기"}</button>{!submitted ? <button type="button" className="answer-action" onClick={onSubmit} disabled={!selected.length}>정답 제출 <ArrowRight size={16} /></button> : correct ? <button type="button" className="answer-action answer-action--success" onClick={onNext}>{isFinalQuestion ? "보스전 입장" : "다음 문제"} <ArrowRight size={16} /></button> : <button type="button" className="retry-action" onClick={onRetry}><RotateCcw size={15} /> 다시 풀기</button>}</div>{showHint && <div className="quest-hint"><Lightbulb size={16} /><span><b>힌트</b>{question.hint}</span></div>}{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <X size={18} />}</span><div><strong>{correct ? "관문에 빛이 켜졌어요." : "아직 이 문은 열리지 않아요."}</strong><p>{question.explanation}</p></div></div>}</div><div className="play-bottom"><span><ShieldCheck size={15} /> {quest.questions.length}문항 뒤에는 보스전이 기다리고 있어요.</span><span>오답은 오답 노트에 저장됨</span></div></section></div></main>;
}

/** Design: the boss gate is a rare, high-stakes one-question poster, not another ordinary quiz card. */
function BossScreen({ quest, boss, selected, submitted, correct, elapsed, attempts, onBack, onToggle, onSubmit, onRetry, onClear }: { quest: Quest; boss: BossChallenge; selected: string[]; submitted: boolean; correct: boolean; elapsed: number; attempts: number; onBack: () => void; onToggle: (option: string) => void; onSubmit: () => void; onRetry: () => void; onClear: () => void }) {
  const question = boss.question;
  return <main className="quest-app"><Header onMap={onBack} title="보스 관문" focus={`${String(quest.id).padStart(2, "0")} · ${boss.title}`} /><section className={`boss-page boss-page--${quest.tone}`}><div className="boss-signal"><QuestArt id={quest.id} className="boss-scene" eager /><p className="quest-kicker">최종 한 문제 · 보스전</p><h1>{boss.title}<br /><em>마지막 봉인을 풀어라.</em></h1><p>{boss.intro}</p><div className="boss-signal__stats"><span><Clock3 size={15} /> {formatTime(elapsed)}</span><span><Target size={15} /> 시도 {attempts}회</span><span><Trophy size={15} /> 보상: {boss.rewardTitle}</span></div></div><div className="boss-sheet"><div className="boss-sheet__bar"><span>보스 문제</span><b>관문 {String(quest.id).padStart(2, "0")} · {quest.concept}</b></div><h2>{question.prompt}</h2>{question.visual && <QuestionVisualCard visual={question.visual} selected={selected} onSelect={onToggle} />}{question.numberLine && <NumberLineDiagram model={question.numberLine} />}{question.multiple && <p className="multi-note">정답을 모두 선택하세요.</p>}<div className="quest-options boss-options">{question.options.map((option, index) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected.includes(option) ? "quest-option--selected" : ""} ${submitted && question.answers.includes(option) ? "quest-option--correct" : ""} ${submitted && selected.includes(option) && !question.answers.includes(option) ? "quest-option--wrong" : ""}`} onClick={() => onToggle(option)}><span>{String.fromCharCode(65 + index)}</span><strong>{option}</strong>{selected.includes(option) && !submitted && <Check size={16} />}{submitted && question.answers.includes(option) && <Check size={16} />}{submitted && selected.includes(option) && !question.answers.includes(option) && <X size={16} />}</button>)}</div><div className="sheet-actions">{!submitted ? <button type="button" className="answer-action boss-answer-action" onClick={onSubmit} disabled={!selected.length}>보스에게 답하기 <ArrowRight size={16} /></button> : correct ? <button type="button" className="answer-action answer-action--success" onClick={onClear}>칭호 받기 <Crown size={16} /></button> : <button type="button" className="retry-action" onClick={onRetry}><RotateCcw size={15} /> 다시 도전</button>}</div>{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <X size={18} />}</span><div><strong>{correct ? "보스의 봉인이 흔들립니다!" : "보스가 아직 길을 막고 있어요."}</strong><p>{question.explanation}</p></div></div>}</div></section></main>;
}

/** Design: a compact reward reveal makes the title feel earned before the usual unlock scene begins. */
function BossClearScreen({ quest, boss, onContinue, onMap }: { quest: Quest; boss: BossChallenge; onContinue: () => void; onMap: () => void }) {
  return <main className="quest-app"><Header onMap={onMap} title="칭호 획득" focus={`관문 ${String(quest.id).padStart(2, "0")} · 보스 격파`} /><section className="boss-clear-page"><div className={`boss-clear-card boss-clear-card--${quest.tone}`}><div className="boss-clear-card__burst">✦</div><QuestArt id={11} className="reward-scene" eager /><p className="quest-kicker">보스 격파 · 특별 칭호 획득</p><h1>{boss.rewardTitle}</h1><p><b>{quest.title}</b>의 마지막 봉인을 풀었습니다. 이 칭호는 업적 보관소에 기록됩니다.</p><div className="boss-clear-card__title"><span>획득 칭호</span><strong>{boss.rewardTitle}</strong></div><button type="button" className="next-quest boss-clear-card__button" onClick={onContinue}>관문 통과 기록하기 <ArrowRight size={17} /></button></div></section></main>;
}

function RuleRecap({ questId }: { questId: number }) {
  const note = studyNotes.find((item) => item.questId === questId) ?? unitStudyNote;
  return <section className="rule-recap" aria-label="이번 관문 핵심 규칙 요약"><div><BookOpenCheck size={17} /><span>학습 종료 · 핵심 규칙 3줄</span></div>{note.rules.slice(0, 3).map((rule, index) => <p key={rule}><b>{index + 1}</b>{rule}</p>)}</section>;
}

/** Design: the review sprint keeps a single weak concept visible, so five questions feel like a focused comeback rather than another full quest. */
function MiniReviewScreen({ queue, weakQuestId, index, selected, submitted, correct, attempts, onBack, onToggle, onSubmit, onRetry, onNext }: { queue: MiniReviewItem[]; weakQuestId: number; index: number; selected: string[]; submitted: boolean; correct: boolean; attempts: number; onBack: () => void; onToggle: (option: string) => void; onSubmit: () => void; onRetry: () => void; onNext: () => void }) {
  const item = queue[index];
  const quest = quests[weakQuestId - 1];
  return <main className="quest-app"><Header onMap={onBack} title="약점 복습전" focus={`집중 개념 · ${quest.concept}`} /><section className={`mini-review-page mini-review-page--${quest.tone}`}><div className="mini-review-header"><div className="mini-review-header__meta"><span className={`quest-tag quest-tag--${quest.tone}`}>{quest.concept}</span><span>집중 복습 · 관문 {String(weakQuestId).padStart(2, "0")}</span></div><div className="mini-review-score">시도 {attempts}회</div></div><div className="mini-review-steps" aria-label="미니 복습전 진행률">{queue.map((question, step) => <span key={`${question.prompt}-${step}`} className={step < index ? "mini-review-step mini-review-step--done" : step === index ? "mini-review-step mini-review-step--current" : "mini-review-step"}>{step < index ? <Check size={14} /> : step + 1}</span>)}</div><div className="mini-review-sheet"><div className="mini-review-sheet__top"><span className={`quest-tag quest-tag--${quest.tone}`}>{item.source}</span><span>문제 {index + 1} / 5</span></div><h2>{item.prompt}</h2>{item.numberLine && <NumberLineDiagram model={item.numberLine} />}{item.visual && <QuestionVisualCard visual={item.visual} selected={selected} onSelect={onToggle} />}{item.interactiveNumberLine && <InteractiveNumberLine model={item.interactiveNumberLine} value={selected[0] ?? ""} onChange={onToggle} />}{item.multiple && <p className="multi-note">정답을 모두 선택하세요.</p>}{item.input ? <label className="direct-answer"><span>숫자로 답을 입력하세요</span><input type="text" inputMode="decimal" value={selected[0] ?? ""} disabled={submitted} onChange={(event) => onToggle(event.target.value)} placeholder="정답 입력" aria-label="정답 입력" /></label> : <div className="quest-options">{item.options.map((option, optionIndex) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected.includes(option) ? "quest-option--selected" : ""} ${submitted && item.answers.includes(option) ? "quest-option--correct" : ""} ${submitted && selected.includes(option) && !item.answers.includes(option) ? "quest-option--wrong" : ""}`} onClick={() => onToggle(option)}><span>{String.fromCharCode(65 + optionIndex)}</span><strong>{option}</strong>{selected.includes(option) && !submitted && <Check size={16} />}{submitted && item.answers.includes(option) && <Check size={16} />}{submitted && selected.includes(option) && !item.answers.includes(option) && <X size={16} />}</button>)}</div>}<div className="sheet-actions">{!submitted ? <button type="button" className="answer-action mini-review-answer" onClick={onSubmit} disabled={!selected.length}>집중 답안 제출 <ArrowRight size={16} /></button> : correct ? <button type="button" className="answer-action answer-action--success" onClick={onNext}>{index === queue.length - 1 ? "결과 확인" : "다음 집중 문제"} <ArrowRight size={16} /></button> : <button type="button" className="retry-action" onClick={onRetry}><RotateCcw size={15} /> 규칙 다시 보고 풀기</button>}</div>{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <X size={18} />}</span><div><strong>{correct ? "약점 규칙을 잡았어요." : "한 번 더 규칙을 확인해요."}</strong><p>{item.explanation}</p></div></div>}</div></section></main>;
}

/** Design: the result is an encouraging recovery stamp, not a performance leaderboard. */
function MiniReviewResultScreen({ quest, correctCount, attempts, onNotes, onRestart }: { quest: Quest; correctCount: number; attempts: number; onNotes: () => void; onRestart: () => void }) {
  const recovered = correctCount >= 4;
  const title = correctCount === 5 ? "약점 정복!" : recovered ? "규칙 회복!" : "한 번 더 단단하게!";
  const copy = correctCount === 5 ? "다섯 문제를 모두 통과했습니다. 이제 이 개념은 자신 있게 다시 써 볼 수 있어요." : recovered ? "핵심 규칙을 다시 잡았습니다. 오답 노트의 남은 문제도 도전해 보세요." : "답을 고를 때 경계값과 상황의 목적을 한 번 더 확인하면 더 단단해져요.";
  return <main className="quest-app"><Header onMap={onNotes} title="복습전 결과" focus={`집중 개념 · ${quest.concept}`} /><section className="mini-result-page"><div className={`mini-result-card mini-result-card--${quest.tone}`}><QuestArt id={quest.id} className="reward-scene" eager /><p className="quest-kicker">5문항 미니 복습전 완료</p><h1>{title}</h1><p>{copy}</p><div className="mini-result-card__stats"><span><Target size={18} /> 정답 <b>{correctCount} / 5</b></span><span><RotateCcw size={18} /> 시도 <b>{attempts}회</b></span></div><div className="mini-result-card__message">약점 개념 <b>{quest.concept}</b></div><div className="mini-result-card__actions"><button type="button" className="map-button" onClick={onNotes}>오답 노트로</button><button type="button" className="next-quest" onClick={onRestart}>5문항 다시 도전 <RotateCcw size={16} /></button></div></div></section></main>;
}

function MistakeBookScreen({ notes, filter, reasonProgress, onFilter, onMap, onStudy, onPractice, onAllPractice, onMiniReview, onReviewConcept, onReviewReason }: { notes: WrongNote[]; filter: NoteFilter; reasonProgress: ReasonProgress; onFilter: (value: NoteFilter) => void; onMap: () => void; onStudy: () => void; onPractice: (note: WrongNote) => void; onAllPractice: () => void; onMiniReview: () => void; onReviewConcept: (questId: number) => void; onReviewReason: (reason: WrongReason) => void }) {
  const filteredNotes = filter === "all" ? notes : notes.filter((note) => note.questId === filter);
  const conceptStats = Object.values(notes.reduce<Record<string, { count: number; questId: number }>>((stats, note) => { const concept = quests[note.questId - 1].concept; stats[concept] = { count: (stats[concept]?.count ?? 0) + note.wrongCount, questId: note.questId }; return stats; }, {})).sort((a, b) => b.count - a.count);
  const primaryWeak = conceptStats[0];
  const reasonStats = Object.entries(notes.reduce<Record<string, number>>((stats, note) => { const reason = deriveWrongReason(note); stats[reason] = (stats[reason] ?? 0) + note.wrongCount; return stats; }, {})).sort((a, b) => b[1] - a[1]).slice(0, 4);
  return <main className="quest-app"><Header onMap={onMap} onStudy={onStudy} /><section className="notes-page"><div className="notes-heading"><div><p className="quest-kicker">오답 노트 · 다시 풀기</p><h1>틀린 문제만<br /><em>다시 잡아요.</em></h1><p>빨간 도장을 받은 문제는 여기에 모입니다.<br />정답을 맞히면 노트에서 사라져요.</p></div><div className="notes-count"><AlertTriangle size={23} /><strong>{notes.length}</strong><span>남은 문제</span></div></div>{notes.length > 0 && <><div className="notes-tools"><div className="note-filters"><button type="button" className={filter === "all" ? "note-filter note-filter--active" : "note-filter"} onClick={() => onFilter("all")}>전체 <b>{notes.length}</b></button>{quests.map((quest) => <button type="button" key={quest.id} className={filter === quest.id ? `note-filter note-filter--${quest.tone} note-filter--active` : `note-filter note-filter--${quest.tone}`} onClick={() => onFilter(quest.id)}>관문 {quest.id} <b>{notes.filter((note) => note.questId === quest.id).length}</b></button>)}</div><button type="button" className="all-review-button" onClick={onAllPractice} disabled={!filteredNotes.length}><RotateCcw size={15} /> {filter === "all" ? "전체 다시 풀기" : "이 관문 다시 풀기"}</button></div><div className="weak-summary"><div className="weak-summary__heading"><div><p className="quest-kicker">오답 분석</p><h2>내가 자주 막히는 곳</h2></div><button type="button" className="notes-study-link" onClick={onStudy}><BookOpen size={15} /> 전체 요점 노트</button></div><div className="weak-summary__grid">{conceptStats.slice(0, 3).map((item, index) => <button type="button" className={`weak-item weak-item--${index === 0 ? "hot" : "normal"}`} key={item.questId} onClick={() => onReviewConcept(item.questId)}><strong>{index + 1}</strong><span>{quests[item.questId - 1].concept}<small>이론 다시 보기 →</small></span><b>{item.count}회</b></button>)}</div></div><section className="reason-recovery"><div className="weak-summary__heading"><div><p className="quest-kicker">오답 원인 분석</p><h2>틀린 이유부터 공략해요</h2></div><span className="reason-recovery__note">기록에서 자동 분류</span></div><div className="reason-recovery__grid">{reasonStats.map(([reason, count], index) => { const progress = reasonProgress[reason as WrongReason]; const percent = progress.started ? Math.round((progress.completed / progress.started) * 100) : 0; return <button type="button" key={reason} className={`reason-card reason-card--${index === 0 ? "hot" : "normal"}`} onClick={() => onReviewReason(reason as WrongReason)}><span>{index + 1}</span><div><strong>{reason}</strong><small>{reason === "수직선 읽기" ? "점·방향·끝점을 다시 읽기" : reason === "조건 모두 확인" ? "표의 조건을 하나씩 대조하기" : reason === "올림·버림·반올림" ? "상황 목적과 바로 아래 자리 보기" : "기준값 포함 여부 확인"} · 복습 완료 {percent}%</small></div><b>{count}회</b></button>; })}</div></section>{primaryWeak && <section className="mini-review-invite"><div><p className="quest-kicker">약점 집중 · 5문항</p><h2><em>{quests[primaryWeak.questId - 1].concept}</em> 미니 복습전</h2><p>오답 횟수가 가장 많은 개념의 실제 문제은행으로 5문항을 구성합니다. 오답 기록은 그대로 두고, 약한 규칙만 집중 연습해요.</p><span><Target size={15} /> 현재 약점 {primaryWeak.count}회 · 관문 {String(primaryWeak.questId).padStart(2, "0")}</span></div><button type="button" onClick={onMiniReview}>5문항 도전 <ArrowRight size={17} /></button></section>}</>}{notes.length === 0 ? <div className="note-empty"><div><BookOpenCheck size={38} /></div><h2>오답 노트가 비었어요.</h2><p>문제를 풀다가 틀린 문제는<br />여기에 자동으로 기록됩니다.</p><button type="button" onClick={onMap}>퀘스트로 돌아가기 <ArrowRight size={16} /></button></div> : filteredNotes.length === 0 ? <div className="note-empty note-empty--small"><div><Check size={30} /></div><h2>이 관문의 오답은 없어요.</h2><p>다른 관문을 골라 보거나<br />새 문제에 도전해 보세요.</p></div> : <div className="note-list">{filteredNotes.map((note, index) => { const quest = quests[note.questId - 1]; return <article className={`note-card note-card--${quest.tone}`} key={note.id}><div className="note-card__stamp">다시!</div><div className="note-card__top"><span className="note-card__reason">{deriveWrongReason(note)}</span><span>NO. {String(index + 1).padStart(2, "0")} · {quest.place}</span><b>{note.wrongCount}번 틀림</b></div><h2>{note.prompt}</h2><div className="note-card__answer"><span>내가 고른 답</span><strong>{note.selected.join(" · ") || "기록 없음"}</strong><span>정답</span><strong>{note.answers.join(" · ")}</strong></div><p>{note.explanation}</p><button type="button" onClick={() => onPractice(note)}>이 문제 다시 풀기 <ArrowRight size={16} /></button></article>; })}</div>}</section></main>;
}

function MistakePracticeScreen({ note, selected, submitted, correct, showSolvedStamp, onBack, onToggle, onSubmit, onRetry }: { note: WrongNote; selected: string[]; submitted: boolean; correct: boolean; showSolvedStamp: boolean; onBack: () => void; onToggle: (option: string) => void; onSubmit: () => void; onRetry: () => void }) {
  const quest = quests[note.questId - 1];
  return <main className="quest-app"><Header onMap={onBack} title="오답 노트" /><section className="note-play-page"><button type="button" className="back-link" onClick={onBack}><ArrowLeft size={15} /> 오답 노트로 돌아가기</button><div className="note-play-heading"><div><p className="quest-kicker">다시 도전 · {quest.place}</p><h1>이번에는<br /><em>통과할 차례!</em></h1></div><div className="note-play-badge">틀린 횟수 <strong>{note.wrongCount}</strong></div></div><div className="question-sheet note-play-sheet"><div className="sheet-header"><span className={`quest-tag quest-tag--${quest.tone}`}>{quest.concept}</span><span className="sheet-status">오답 복습</span></div><h3>{note.prompt}</h3>{note.numberLine && <NumberLineDiagram model={note.numberLine} />}{note.visual && <QuestionVisualCard visual={note.visual} selected={selected} onSelect={onToggle} />}{note.interactiveNumberLine && <InteractiveNumberLine model={note.interactiveNumberLine} value={selected[0] ?? ""} onChange={onToggle} />}{note.multiple && <p className="multi-note">정답을 모두 선택하세요.</p>}{note.input ? <label className="direct-answer"><span>숫자로 답을 입력하세요</span><input type="text" inputMode="decimal" value={selected[0] ?? ""} disabled={submitted} onChange={(event) => onToggle(event.target.value)} placeholder="정답 입력" aria-label="정답 입력" /></label> : <div className="quest-options">{note.options.map((option, index) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected.includes(option) ? "quest-option--selected" : ""} ${submitted && note.answers.includes(option) ? "quest-option--correct" : ""} ${submitted && selected.includes(option) && !note.answers.includes(option) ? "quest-option--wrong" : ""}`} onClick={() => onToggle(option)}><span>{String.fromCharCode(65 + index)}</span><strong>{option}</strong>{submitted && note.answers.includes(option) && <Check size={16} />}{submitted && selected.includes(option) && !note.answers.includes(option) && <X size={16} />}</button>)}</div>}<div className="sheet-actions">{!submitted ? <button type="button" className="answer-action" onClick={onSubmit} disabled={!selected.length}>정답 제출 <ArrowRight size={16} /></button> : correct ? <button type="button" className="answer-action answer-action--success" onClick={onBack}>오답 노트로 돌아가기 <ArrowRight size={16} /></button> : <button type="button" className="retry-action" onClick={onRetry}><RotateCcw size={15} /> 다시 고르기</button>}</div>{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <X size={18} />}</span><div><strong>{correct ? "오답 노트에서 지웠어요." : "빨간 도장이 한 번 더 찍혔어요."}</strong><p>{note.explanation}</p></div></div>}</div>{showSolvedStamp && <div className="solved-overlay" role="status"><div className="solved-stamp">해결<br />완료</div><p>이 문제는 오답 노트에서 사라져요!</p></div>}</section></main>;
}

function UnlockScreen({ sequence, noteCount, onMap, onNext, onAchievements }: { sequence: UnlockSequence; noteCount: number; onMap: () => void; onNext: () => void; onAchievements: () => void }) {
  const [phase, setPhase] = useState(0);
  const fromQuest = quests[sequence.from - 1];
  const nextQuest = sequence.next ? quests[sequence.next - 1] : null;
  const fromIndex = sequence.from - 1;
  const nextIndex = sequence.next ? sequence.next - 1 : fromIndex;
  const point = (index: number) => ({ x: 14 + (index % 4) * 24, y: 20 + Math.floor(index / 4) * 30 });
  const from = point(fromIndex);
  const to = point(nextIndex);
  useEffect(() => { const timers = [window.setTimeout(() => setPhase(1), 360), window.setTimeout(() => setPhase(2), 1320), window.setTimeout(() => setPhase(3), 2280)]; return () => timers.forEach(window.clearTimeout); }, []);
  const message = phase === 0 ? "통과 기록을 지도에 새기는 중" : phase === 1 ? "빛의 길이 다음 관문까지 이어집니다" : phase === 2 ? "봉인에 금이 갔습니다" : nextQuest ? "다음 관문이 열렸습니다" : "경계의 성 모든 관문을 통과했습니다";
  return <main className="quest-app"><Header onMap={phase >= 3 ? onMap : undefined} onAchievements={phase >= 3 ? onAchievements : undefined} noteCount={noteCount} title="관문 해금" focus={`관문 ${String(sequence.from).padStart(2, "0")} 통과`} /><section className="unlock-page"><div className="unlock-heading"><p className="quest-kicker">관문 통과 · 기록 갱신</p><h1>{fromQuest.title}<br /><em>길이 열립니다.</em></h1><p>{message}</p></div><div className={`unlock-map unlock-map--phase-${phase}`}><svg className="unlock-route-svg" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><line className="unlock-route-base" x1={from.x} y1={from.y} x2={to.x} y2={to.y} /><line className="unlock-route-light" x1={from.x} y1={from.y} x2={to.x} y2={to.y} /></svg><div className="unlock-gate unlock-gate--cleared" style={{ left: `${from.x}%`, top: `${from.y}%` }}><QuestArt id={fromQuest.id} /><span className="unlock-gate__label">관문 {String(sequence.from).padStart(2, "0")}<b>통과</b></span></div>{nextQuest ? <div className="unlock-gate unlock-gate--next" style={{ left: `${to.x}%`, top: `${to.y}%` }}><QuestArt id={nextQuest.id} /><span className="unlock-gate__label">관문 {String(nextQuest.id).padStart(2, "0")}<b>{phase < 3 ? "봉인" : "열림"}</b></span>{phase >= 2 && <i className="unlock-crack">봉인 해제</i>}</div> : <div className="unlock-gate unlock-gate--final" style={{ left: `${to.x}%`, top: `${to.y}%` }}><QuestArt id={11} /><span className="unlock-gate__label">최종 관문<b>완료</b></span></div>}<div className="unlock-spark unlock-spark--a">✦</div><div className="unlock-spark unlock-spark--b">✦</div><div className="unlock-spark unlock-spark--c">✦</div></div><RuleRecap questId={fromQuest.id} /><div className="unlock-record"><div><Clock3 size={18} /><span>이번 기록</span><strong>{formatTime(sequence.result.last ?? 0)}</strong></div><div><Target size={18} /><span>정확도</span><strong>{sequence.result.accuracy}%</strong></div><div><Crown size={18} /><span>최고 기록</span><strong>{formatTime(sequence.result.best ?? 0)}</strong></div></div><div className="unlock-actions"><button type="button" className="map-button" onClick={onMap} disabled={phase < 3}>지도에서 확인</button><button type="button" className="next-quest unlock-next-button" onClick={onNext} disabled={phase < 3}>다음 관문 입장 <ArrowRight size={17} /></button></div></section></main>;
}

function ResultScreen({ quest, result, noteCount, onMap, onNotes, onNext }: { quest: Quest; result: RecordValue; noteCount: number; onMap: () => void; onNotes: () => void; onNext: () => void }) {
  const nextQuest = quest.id < quests.length ? quests[quest.id] : null;
  return <main className="quest-app"><Header onMap={onMap} onNotes={onNotes} noteCount={noteCount} focus={nextQuest ? `${String(nextQuest.id).padStart(2, "0")} · 봉인 해제` : "최종 관문 통과"} /><section className="result-page"><QuestArt id={quest.id} className="reward-scene" eager /><p className="quest-kicker">차시 통과 · {quest.gate}</p><h1>{quest.title}<br /><em>관문 통과!</em></h1><p className="result-copy">{quest.questions.length}문항을 끝까지 풀어 {quest.place}을 통과했어요. 다음 지도 조각이 모습을 드러냈습니다.</p><div className="result-stats"><div><Clock3 size={19} /><span>이번 기록</span><strong>{formatTime(result.last ?? 0)}</strong></div><div><Target size={19} /><span>정확도</span><strong>{result.accuracy}%</strong></div><div><Sparkles size={19} /><span>최고 기록</span><strong>{formatTime(result.best ?? 0)}</strong></div></div>{nextQuest && <div className="unlock-reward"><ShieldCheck size={19} /><div><span>봉인 해제</span><strong>관문 {String(nextQuest.id).padStart(2, "0")} · {nextQuest.title}</strong></div><b>열림</b></div>}<div className="result-note"><Crown size={17} /><span>{result.last === result.best ? "개인 최고 기록을 새로 남겼어요." : "나의 최고 기록과 비교해 보세요."}</span></div><div className="result-actions"><button type="button" className="map-button" onClick={onMap}>지도 확인</button>{noteCount > 0 && <button type="button" className="map-button" onClick={onNotes}>오답 노트 {noteCount}개</button>}{quest.id < quests.length && <button type="button" className="next-quest" onClick={onNext}>다음 관문 열기 <ArrowRight size={17} /></button>}</div></section></main>;
}

function BossPrepScreen({ quest, onBack, onStart }: { quest: Quest; onBack: () => void; onStart: () => void }) {
  const rules = quest.id <= 4
    ? ["기준값을 포함하면 채워진 점(●)이에요.", "기준값을 포함하지 않으면 빈 점(○)이에요.", "큰 수는 오른쪽, 작은 수는 왼쪽으로 읽어요."]
    : quest.id <= 8
      ? ["부족하지 않게 모두 준비하면 올림이에요.", "완전한 묶음만 세면 버림이에요.", "가장 가까운 값은 바로 아래 자리 5 이상이면 올려요."]
      : quest.id === 9 ? ["가로·세로·높이를 더해 크기를 구해요.", "무게와 크기로 요금을 각각 찾아요.", "두 요금 중 더 높은 요금을 내요."]
      : ["조건이 두 개면 각각 확인한 뒤 모두 만족해야 해요.", "표에서 기준값 포함 여부를 먼저 표시해요.", "문제의 목적에 맞는 어림 방법을 선택해요."];
  return <main className="quest-app"><Header onMap={onBack} title="보스전 준비" focus={`${String(quest.id).padStart(2, "0")} · 규칙 회상`} /><section className={`boss-prep-page boss-prep-page--${quest.tone}`}><div className="boss-prep-card"><QuestArt id={quest.id} className="prep-scene" eager /><p className="quest-kicker">보스 입장 전 · 3문장 회상</p><h1>규칙을 먼저<br /><em>손에 쥐세요.</em></h1><p>{quest.concept} 관문에서 가장 자주 쓰는 규칙입니다. 세 문장을 읽고 보스 문제로 들어가요.</p><div className="boss-prep-rules">{rules.map((rule, index) => <div key={rule}><b>{index + 1}</b><span>{rule}</span></div>)}</div><div className="boss-prep-actions"><button type="button" className="back-link" onClick={onBack}><ArrowLeft size={15} /> 지도</button><button type="button" className="start-quest" onClick={onStart}>보스전 입장 <ArrowRight size={17} /></button></div></div></section></main>;
}
import { canOpenQuest } from "@/lib/questAccess";
